import {buildCreditAssessment} from '../../../lib/credit-engine/credit-assessment/engine.ts';
import {id,stable,same,rank} from '../../../lib/credit-engine/credit-assessment/common.ts';
export const fingerprint=e=>id('assessment-golden',e);
const matches=(a,b)=>Object.entries(b).every(([k,v])=>same(a[k],v));
export function expectations(e,r,error=null){const out=[];const check=(ok,code,expected,actual,level='HARD')=>{if(!ok)out.push({mismatchId:id('assessment-mismatch',e.caseId,code,expected,actual),code,expected,actual,level});};const ex=e.expected;
 if(ex.invalid){check(!!error&&error.includes(ex.invalid),'EXPECTED_REJECTION',ex.invalid,error);return out;}check(!!r&&!error,'EXECUTION',true,error);if(!r)return out;
 for(const k of ['status','confidence','comparable'])if(Object.hasOwn(ex,k))check(r[k]===ex[k],k.toUpperCase(),ex[k],r[k]);
 for(const [k,obj]of [['indexValue',r.indexReference],['readinessLevel',r.readinessReference]])if(Object.hasOwn(ex,k))check(obj[k==='indexValue'?'value':'level']===ex[k],k,ex[k],obj);
 for(const d of ex.requiredDrivers??[])check(r.drivers.some(v=>matches(v,d)),'MISSING_DRIVER',d,r.drivers);
 for(const d of ex.forbiddenDrivers??[])check(!r.drivers.some(v=>matches(v,d)),'FORBIDDEN_DRIVER',d,r.drivers);
 if(ex.driverCount!==undefined)check(r.drivers.length===ex.driverCount,'DRIVER_COUNT',ex.driverCount,r.drivers.length);
 for(const d of ex.dimensions??[])check(r.dimensions.some(v=>matches(v,d)),'DIMENSION',d,r.dimensions);
 for(const d of ex.requiredLimitations??[])check(r.limitations.some(v=>matches(v,d)),'MISSING_LIMITATION',d,r.limitations);
 for(const d of ex.forbiddenLimitations??[])check(!r.limitations.some(v=>matches(v,d)),'FORBIDDEN_LIMITATION',d,r.limitations);
 for(const c of ex.requiredContext??[]){const all=Object.values(r.context).flat();check(all.some(v=>v.relation.effect===c.effect&&(!c.code||v.relation.code===c.code)&&(!c.targetRiskCode||r.drivers.some(d=>d.riskCode===c.targetRiskCode&&v.relation.targetRiskFindingIds.includes(d.riskFindingId)))),'CONTEXT_LINK',c,all);}
 const primary=r.primaryDriverIds.map(id=>r.drivers.find(d=>d.driverId===id)?.riskCode);if(ex.primaryCodes)check(same(primary,ex.primaryCodes)&&stable(primary)===stable(ex.primaryCodes),'PRIMARY_ORDER',ex.primaryCodes,primary);
 if(ex.primaryCount!==undefined)check(primary.length===ex.primaryCount,'PRIMARY_COUNT',ex.primaryCount,primary.length);
 if(ex.caseDefinitionStatus)check(r.financingCase.definitionStatus===ex.caseDefinitionStatus,'CASE_DEFINITION',ex.caseDefinitionStatus,r.financingCase.definitionStatus);
 for(const[k,v]of Object.entries(ex.summary??{}))check(r.summary[k]===v,'SUMMARY_'+k,v,r.summary[k]);
 if(ex.invariants){const x=e.input;check(r.indexReference.value===x.prescoreIndex.value,'NO_INDEX_RECALCULATION',x.prescoreIndex.value,r.indexReference.value);check(r.readinessReference.level===x.financingReadiness.level,'NO_READINESS_RECALCULATION',x.financingReadiness.level,r.readinessReference.level);check(rank(r.confidence)<=Math.min(rank(x.prescoreIndex.confidence),rank(x.financingReadiness.confidence)),'CONFIDENCE',true,r.confidence);check(r.drivers.every(d=>d.kind==='GLOBAL_STOP'||x.prescoreIndex.contributions.some(c=>c.contributionId===d.indexContributionId&&c.riskFindingId===d.riskFindingId&&c.finalPenaltyPoints===d.finalPenaltyPoints&&c.basePenaltyPoints===d.basePenaltyPoints&&c.contextModifierPercent===d.contextModifierPercent)),'INDEX_SINGLE_SOURCE',true,r.drivers);check(r.dimensions.filter(d=>d.indexComponent).every(d=>x.prescoreIndex.components.some(c=>c.component===d.indexComponent&&c.scorePoints===d.scorePoints&&c.finalPenalty===d.finalPenalty&&c.maxPoints===d.maxPoints)),'COMPONENTS_COPIED',true,r.dimensions);}
 if(ex.defect){const driver=r.drivers.find(d=>d.riskCode==='RISK-BKI-CURRENT-OVERDUE');check(!!driver&&driver.reasonCodes.includes('CURRENT_OVERDUE')&&r.drivers.every(d=>!d.reasonCodes.some(s=>['DELINQUENCY_1_29','DELINQUENCY_30_59','DELINQUENCY_60_PLUS'].includes(s))),'PERMANENT_DEFECT_REGRESSION',true,r.drivers);}
 for(const a of ex.reviewAssertions??[])check(r[a.field]===a.value,'REVIEW_'+a.field,a.value,r[a.field],'REVIEW');return out;}
export function compareAssessment(a,b,field='drivers',operator='EQ'){const x=field==='output'?stable(a):a[field],y=field==='output'?stable(b):b[field];return operator==='EQ'?stable(x)===stable(y):operator==='GT'?x>y:x<y;}
export function runAssessmentPack(pack){for(const e of pack.entries)if(pack.fingerprints[e.caseId]!==fingerprint(e))throw Error('ASSESSMENT_GOLDEN_FINGERPRINT_MISMATCH');const rs=pack.entries.map(e=>{const before=stable(e.input);let actual=null,error=null;try{actual=buildCreditAssessment(e.input);}catch(ex){error=ex.message;}const mismatches=expectations(e,actual,error);if(stable(e.input)!==before)mismatches.push({code:'UPSTREAM_MUTATED',level:'HARD'});return {caseId:e.caseId,actual,error,mismatches};});for(const e of pack.entries){const r=rs.find(r=>r.caseId===e.caseId);for(const p of e.expected.relative??[]){const other=rs.find(r=>r.caseId===p.other);if(!r.actual||!other?.actual||!compareAssessment(r.actual,other.actual,p.field,p.operator))r.mismatches.push({code:'PAIRWISE_MISMATCH',level:'HARD',expected:p});}}return rs.map(r=>({...r,result:r.mismatches.some(m=>m.level==='HARD')?'FAIL':r.mismatches.length?'REVIEW':'PASS'}));}
